scan_regions = input('scan_regions')
exempt       = (input('exempt_assets') || {})['CKV_AWS_76'] || []

control 'CKV_AWS_76' do
  title 'Ensure API Gateway has Access Logging enabled'

  desc <<~DESC
    Checkov asserts this against Terraform. This profile asserts it against
    the aws_api_gateway_stage resources that actually exist, enumerated
    through the two-step (parent -> child) declarative API spec.

    Checkov reads the access_log_settings block in HCL. This reads
    GetStages, so a stage whose logging was switched off in the console
    after deploy is assessed too.
  DESC

  desc 'rationale', <<~RATIONALE
    A stage with no access log destination keeps no record of who called
    which route. There is nothing to review after an incident and nothing to
    feed detection.
  RATIONALE

  desc 'check', <<~CHECK
    Checkov looks for: aws_api_gateway_stage:
    access_log_settings/[0]/destination_arn is CKV_ANY;
    aws_apigatewayv2_stage: access_log_settings/[0]/destination_arn is
    CKV_ANY
  CHECK

  desc 'fix', <<~'FIX'
    Terraform — aws_api_gateway_stage:

      resource "aws_cloudwatch_log_group" "apigw" {
        name              = "/aws/apigateway/example"
        retention_in_days = 365
      }

      resource "aws_api_gateway_stage" "example" {
        rest_api_id   = aws_api_gateway_rest_api.example.id
        deployment_id = aws_api_gateway_deployment.example.id
        stage_name    = "prod"

        access_log_settings {
          destination_arn = aws_cloudwatch_log_group.apigw.arn
          format          = jsonencode({ requestId = "$context.requestId", ip = "$context.identity.sourceIp", status = "$context.status" })
        }
      }

    Out of band — aws_api_gateway_stage:

      aws apigateway update-stage --rest-api-id <api-id> --stage-name prod --patch-operations op=replace,path=/accessLogSettings/destinationArn,value=<log-group-arn> op=replace,path=/accessLogSettings/format,value='$context.requestId'

    Terraform — aws_apigatewayv2_stage:

      resource "aws_apigatewayv2_stage" "example" {
        api_id      = aws_apigatewayv2_api.example.id
        name        = "prod"
        auto_deploy = true

        access_log_settings {
          destination_arn = aws_cloudwatch_log_group.apigw.arn
          format          = jsonencode({ requestId = "$context.requestId", status = "$context.status" })
        }
      }

    Out of band — aws_apigatewayv2_stage:

      aws apigatewayv2 update-stage --api-id <api-id> --stage-name prod --access-log-settings DestinationArn=<log-group-arn>,Format='$context.requestId'
  FIX

  tag checkov_id:            'CKV_AWS_76'
  tag checkov_category:      'LOGGING'
  tag checkov_version:       '3.3.16'
  tag checkov_kind:          'value'
  tag tf_resources:          %w[aws_api_gateway_stage aws_apigatewayv2_stage]
  tag tf_docs:               'https://registry.terraform.io/providers/hashicorp/aws/latest/docs/resources/api_gateway_stage#access-log-settings'
